        "owner_compilation":"R536_owner_compilation_ref",
        "root_cache_compile_binding":"R536_root_cache_compile_binding_ref",
        "root_finite_word_cache_source_preparation":"R536_root_cache_preparation_ref",
        "root_finite_word_cache_source_binding":"R536_root_cache_source_binding_ref",
        "root_finite_word_cache_compiler_installation":"R536_root_cache_installation_ref",
        "physical_source_input_binding":"R536_physical_source_input_binding_ref",
    }

    def __init__(self):
        self.values={name:[] for name in self.REF_KEYS}
        self.originals={name:[] for name in self.REF_KEYS}
        self.seen={name:{} for name in self.REF_KEYS}

    def share(self,name,value,display=None):
        # Absent fields are not passed here. Present null/scalar/list values
        # remain literal, so missing and null never become one table entry.
